-- 조건 하나를 만든다

package study.boot.cond;

public class OnMacCondition implements Condition {
    @Override
    public boolean matches(ConditionContext ctx, AnnotatedTypeMetadata meta) {
        String os = ctx.getEnvironment().getProperty("os.name");
        System.out.println("[조건] os.name = " + os);
        return os != null && os.startsWith("Mac");
    }
}

@Configuration
public class OsConfig {
    @Bean
    @Conditional(OnMacCondition.class)
    public String macBean() { return "맥에서만"; }

    @Bean
    public String alwaysBean() { return "늘"; }
}


