-- 조건은 무엇을 볼 수 있나

public class SnoopCondition implements Condition {
    public boolean matches(ConditionContext ctx, AnnotatedTypeMetadata meta) {
        var reg = ctx.getRegistry();
        System.out.println("[본다] 정의 수   = " + reg.getBeanDefinitionCount());
        System.out.println("[본다] 클래스로더 = " + (ctx.getClassLoader() != null));
        System.out.println("[본다] 리소스     = " + (ctx.getResourceLoader() != null));
        System.out.println("[본다] 붙은 자리  = " + meta.getAnnotationTypes());
        return true;
    }
}

