-- 빈을 꺼내려 하면

public boolean matches(ConditionContext ctx, AnnotatedTypeMetadata meta) {
    var bf = ctx.getBeanFactory();
    try {
        var om = bf.getBean(ObjectMapper.class);
        System.out.println("[꺼냄] " + om);
        return true;
    } catch (Exception e) {
        System.out.println("[꺼냄] " + e.getClass().getSimpleName());
        return false;
    }
}

