--   6.7절에서 이 보고서를 제대로 읽는다


-- 이유를 적어 줄 수도 있다

public class OnMacCondition extends SpringBootCondition {
    @Override
    public ConditionOutcome getMatchOutcome(ConditionContext ctx,
                                            AnnotatedTypeMetadata meta) {
        String os = ctx.getEnvironment().getProperty("os.name");
        boolean ok = os != null && os.startsWith("Mac");
        return new ConditionOutcome(ok,
            ConditionMessage.forCondition("OnMac")
                .because("os.name = " + os));
    }
}

