-- 순서에 기대면 흔들린다

public class OnAlwaysCondition implements Condition {
    static int n = 0;
    public boolean matches(ConditionContext ctx, AnnotatedTypeMetadata meta) {
        System.out.println("[순서] " + (++n) + " " + meta.getAnnotationTypes());
        return true;
    }
}

